package com.hbm.blocks.machine;

import java.util.Random;

import com.hbm.blocks.ModBlocks;
import com.hbm.inventory.fluid.FluidType;
import com.hbm.inventory.fluid.tank.FluidTank;
import com.hbm.lib.RefStrings;
import com.hbm.render.block.ct.CT;
import com.hbm.render.block.ct.CTStitchReceiver;
import com.hbm.render.block.ct.IBlockCT;
import com.hbm.tileentity.machine.TileEntityPWRController;

import api.hbm.fluidmk2.IFluidReceiverMK2;
import api.hbm.redstoneoverradio.IRORInteractive;
import api.hbm.redstoneoverradio.IRORValueProvider;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import net.minecraft.block.Block;
import net.minecraft.block.BlockContainer;
import net.minecraft.block.material.Material;
import com.hbm.render.icon.IIconRegister;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.Blocks;
import net.minecraft.inventory.ISidedInventory;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.tileentity.TileEntity;
import com.hbm.render.icon.IIcon;
import net.minecraft.world.IBlockAccess;
import net.minecraft.world.World;
import com.hbm.lib.ForgeDirection;

public class BlockPWR extends BlockContainer implements IBlockCT {

	@SideOnly(Side.CLIENT) protected IIcon iconPort;

	public BlockPWR(Material mat) {
		super(mat);
	}

	@Override
	public int getRenderType() {
		return CT.renderID;
	}

	@Override
	public Item getItemDropped(int i, Random rand, int j)  {
		return null;
	}

	@SideOnly(Side.CLIENT) public CTStitchReceiver rec;
	@SideOnly(Side.CLIENT) public CTStitchReceiver recPort;

	@SideOnly(Side.CLIENT)
	public void registerBlockIcons(IIconRegister reg) {
		super.registerBlockIcons(reg);
		this.iconPort = reg.registerIcon(RefStrings.MODID + ":pwr_casing_port");
		this.rec = IBlockCT.primeReceiver(reg, this.blockIcon.getIconName(), this.blockIcon);
		this.recPort = IBlockCT.primeReceiver(reg, this.iconPort.getIconName(), this.iconPort);
	}

	@Override
	public IIcon[] getFragments(IBlockAccess world, int x, int y, int z) {
		int meta = world.getBlockMetadata(x, y, z);
		if(meta == 1) return recPort.fragCache;
		return rec.fragCache;
	}

	@Override
	public boolean canConnect(IBlockAccess world, int x, int y, int z, Block block) {
		return block == ModBlocks.pwr_block || block == ModBlocks.pwr_controller;
	}

	@Override
	public TileEntity createNewTileEntity(World world, int meta) {
		return new TileEntityBlockPWR();
	}

	@Override
	public void breakBlock(World world, int x, int y, int z, Block block, int meta) {

		TileEntity tile = world.getTileEntity(x, y, z);

		if(tile instanceof TileEntityBlockPWR) {
			TileEntityBlockPWR pwr = (TileEntityBlockPWR) tile;
			world.removeTileEntity(x, y, z);
			if(pwr.block != null) {
				world.setBlock(x, y, z, pwr.block);
				TileEntity controller = world.getTileEntity(pwr.coreX, pwr.coreY, pwr.coreZ);

				if(controller instanceof TileEntityPWRController) {
					((TileEntityPWRController) controller).assembled = false;
				}
			}
		} else {
			world.removeTileEntity(x, y, z);
		}
		super.breakBlock(world, x, y, z, block, meta);
	}

	public static class TileEntityBlockPWR extends TileEntity implements IFluidReceiverMK2, ISidedInventory, IRORValueProvider, IRORInteractive, net.minecraft.util.ITickable {

		public Block block;
		public int coreX;
		public int coreY;
		public int coreZ;

		@Override
		public void update() {

			if(!worldObj.isRemote) {

				if(worldObj.getTotalWorldTime() % 20 == 0 && block != null) {

					TileEntityPWRController controller = getCore();

					if(controller != null) {
						if(!controller.assembled) {
							this.getBlockType().breakBlock(worldObj, xCoord, yCoord, zCoord, this.getBlockType(), this.getBlockMetadata());
						}
					} else if(worldObj.getChunkProvider().chunkExists(coreX >> 4, coreZ >> 4)) {
						this.getBlockType().breakBlock(worldObj, xCoord, yCoord, zCoord, this.getBlockType(), this.getBlockMetadata());
					}
				}
			}
		}

		@Override
		public void readFromNBT(NBTTagCompound nbt) {
			super.readFromNBT(nbt);

			block = Block.getBlockById(nbt.getInteger("block"));
			if(block != Blocks.air) {
				coreX = nbt.getInteger("cX");
				coreY = nbt.getInteger("cY");
				coreZ = nbt.getInteger("cZ");
			} else {
				block = null;
			}
		}

		@Override
		public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
			super.writeToNBT(nbt);

			if(block != null) {
				nbt.setInteger("block", Block.getIdFromBlock(block));
				nbt.setInteger("cX", coreX);
				nbt.setInteger("cY", coreY);
				nbt.setInteger("cZ", coreZ);
			}
			return nbt;
		}

		@Override
		public void markDirty() {
			if(this.world != null) {
				this.world.markTileEntityChunkModified(this.xCoord, this.yCoord, this.zCoord, this);
			}
		}

		public TileEntityPWRController cachedCore;

		protected TileEntityPWRController getCore() {

			if(cachedCore != null && !cachedCore.isInvalid()) return cachedCore;

			if(worldObj.getChunkProvider().chunkExists(coreX >> 4, coreZ >> 4)) {

				TileEntity tile = worldObj.getTileEntity(coreX, coreY, coreZ);
				if(tile instanceof TileEntityPWRController) {
					TileEntityPWRController controller = (TileEntityPWRController) tile;
					cachedCore = controller;
					return controller;
				}
			}

			return null;
		}

		@Override
		public long transferFluid(FluidType type, int pressure, long fluid) {

			if(this.getBlockMetadata() != 1) return fluid;
			if(block == null) return fluid;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.transferFluid(type, pressure, fluid);

			return fluid;
		}

		@Override
		public long getDemand(FluidType type, int pressure) {
			if(this.getBlockMetadata() != 1) return 0;
			if(block == null) return 0;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getDemand(type, pressure);
			return 0;
		}

		@Override
		public FluidTank[] getAllTanks() {
			if(this.getBlockMetadata() != 1) return FluidTank.EMPTY_ARRAY;
			if(block == null) return FluidTank.EMPTY_ARRAY;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getAllTanks();
			return FluidTank.EMPTY_ARRAY;
		}

		@Override
		public boolean canConnect(FluidType type, ForgeDirection dir) {
			return this.getBlockMetadata() == 1;
		}

		@Override
		public int getSizeInventory() {

			if(this.getBlockMetadata() != 1) return 0;
			if(block == null) return 0;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getSizeInventory();

			return 0;
		}

		@Override
		public ItemStack getStackInSlot(int slot) {

			if(this.getBlockMetadata() != 1) return null;
			if(block == null) return null;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getStackInSlot(slot);

			return null;
		}

		@Override
		public ItemStack decrStackSize(int slot, int amount) {

			if(this.getBlockMetadata() != 1) return null;
			if(block == null) return null;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.decrStackSize(slot, amount);

			return null;
		}

		@Override
		public ItemStack getStackInSlotOnClosing(int slot) {

			if(this.getBlockMetadata() != 1) return null;
			if(block == null) return null;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getStackInSlotOnClosing(slot);

			return null;
		}

		@Override
		public void setInventorySlotContents(int slot, ItemStack stack) {

			if(this.getBlockMetadata() != 1) return;
			if(block == null) return;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) controller.setInventorySlotContents(slot, stack);
		}

		@Override
		public int getInventoryStackLimit() {

			if(this.getBlockMetadata() != 1) return 0;
			if(block == null) return 0;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getInventoryStackLimit();

			return 0;
		}

		@Override public boolean isUsableByPlayer(EntityPlayer player) { return false; }
		@Override public void openInventory(EntityPlayer player) { }
		@Override public void closeInventory(EntityPlayer player) { }
		@Override public String getInventoryName() { return ""; }
		@Override public boolean hasCustomInventoryName() { return false; }

		@Override
		public boolean isItemValidForSlot(int slot, ItemStack stack) {

			if(this.getBlockMetadata() != 1) return false;
			if(block == null) return false;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.isItemValidForSlot(slot, stack);

			return false;
		}

		@Override
		public int[] getSlotsForFace(net.minecraft.util.EnumFacing nativeFace) {
			int side = com.hbm.lib.ForgeDirection.fromEnumFacing(nativeFace).ordinal();

			if(this.getBlockMetadata() != 1) return new int[0];
			if(block == null) return new int[0];
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getSlotsForFace(com.hbm.lib.ForgeDirection.getOrientation(side).toEnumFacing());

			return new int[0];
		}

		@Override
		public boolean canInsertItem(int slot, ItemStack stack, net.minecraft.util.EnumFacing nativeFace) {
			int side = com.hbm.lib.ForgeDirection.fromEnumFacing(nativeFace).ordinal();

			if(this.getBlockMetadata() != 1) return false;
			if(block == null) return false;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.canInsertItem(slot, stack, com.hbm.lib.ForgeDirection.getOrientation(side).toEnumFacing());

			return false;
		}

		@Override
		public boolean canExtractItem(int slot, ItemStack stack, net.minecraft.util.EnumFacing nativeFace) {
			int side = com.hbm.lib.ForgeDirection.fromEnumFacing(nativeFace).ordinal();

			if(this.getBlockMetadata() != 1) return false;
			if(block == null) return false;
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.canExtractItem(slot, stack, com.hbm.lib.ForgeDirection.getOrientation(side).toEnumFacing());

			return false;
		}

		public boolean isLoaded = true;

		@Override
		public boolean isLoaded() {
			return isLoaded;
		}

		@Override
		public void onChunkUnload() {
			super.onChunkUnload();
			this.isLoaded = false;
		}

		@Override
		public String[] getFunctionInfo() {
			if(this.getBlockMetadata() != 1) return new String[0];
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.getFunctionInfo();
			return new String[0];
		}

		@Override
		public String provideRORValue(String name) {
			if(this.getBlockMetadata() != 1) return "";
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.provideRORValue(name);
			return "";
		}

		@Override
		public String runRORFunction(String name, String[] params) {
			if(this.getBlockMetadata() != 1) return "";
			TileEntityPWRController controller = this.getCore();
			if(controller != null) return controller.runRORFunction(name, params);
			return "";
		}
	}
}

package com.hbm.tileentity;

import com.hbm.handler.threading.PacketThreading;
import com.hbm.packet.toclient.BufPacket;
import com.hbm.sound.AudioWrapper;

import api.hbm.tile.ILoadedTile;
import net.minecraftforge.fml.common.network.NetworkRegistry;
import io.netty.buffer.ByteBuf;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.tileentity.TileEntity;

public class TileEntityLoadedBase extends TileEntity implements ILoadedTile, IBufPacketReceiver {

	public boolean isLoaded = true;
	public boolean muffled = false;

	@Override
	public boolean isLoaded() {
		return isLoaded;
	}

	@Override
	public void onChunkUnload() {
		super.onChunkUnload();
		this.isLoaded = false;
	}

	public AudioWrapper createAudioLoop() { return null; }

	public AudioWrapper rebootAudio(AudioWrapper wrapper) {
		wrapper.stopSound();
		AudioWrapper audio = createAudioLoop();
		audio.startSound();
		return audio;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);
		this.muffled = nbt.getBoolean("muffled");
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		super.writeToNBT(nbt);
		nbt.setBoolean("muffled", muffled);
		return nbt;
	}

	public float getVolume(float baseVolume) {
		return muffled ? baseVolume * 0.1F : baseVolume;
	}

	private ByteBuf lastPackedBuf;

	@Override
	public void serialize(ByteBuf buf) {
		buf.writeBoolean(muffled);
	}

	@Override
	public void deserialize(ByteBuf buf) {
		this.muffled = buf.readBoolean();
	}

	/** Sends a sync packet that uses ByteBuf for efficient information-cramming */
	public void networkPackNT(int range) {
		if(worldObj.isRemote) return;

		BufPacket packet = new BufPacket(xCoord, yCoord, zCoord, this);

		ByteBuf preBuf = packet.getCompiledBuffer();

		// Don't send unnecessary packets, except for maybe one every second or so.
		// If we stop sending duplicate packets entirely, this causes issues when
		// a client unloads and then loads back a chunk with an unchanged tile entity.
		// For that client, the tile entity will appear default until anything changes about it.
		// In my testing, this can be reliably reproduced with a full fluid barrel, for instance.
		// I think it might be fixable by doing something with getDescriptionPacket() and onDataPacket(),
		// but this sidesteps the problem for the mean time.
		if(preBuf.equals(lastPackedBuf) && this.world.getTotalWorldTime() % 20 != 0) return;

		this.lastPackedBuf = preBuf.copy();

		PacketThreading.createAllAroundThreadedPacket(packet, new NetworkRegistry.TargetPoint(this.world.provider.dimensionId, xCoord, yCoord, zCoord, range));
	}

}

package com.hbm.tileentity;

import java.util.List;

import com.hbm.dim.CelestialBody;
import com.hbm.dim.orbit.WorldProviderOrbit;
import com.hbm.dim.trait.CBT_Atmosphere;
import com.hbm.handler.atmosphere.AtmosphereBlob;
import com.hbm.handler.atmosphere.ChunkAtmosphereManager;
import com.hbm.inventory.fluid.Fluids;
import com.hbm.util.fauxpointtwelve.DirPos;

import net.minecraft.block.Block;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.ISidedInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.world.World;
import com.hbm.lib.ForgeDirection;
import net.minecraftforge.fluids.FluidTank;

public abstract class TileEntityMachineBase extends TileEntityLoadedBase implements ISidedInventory, net.minecraft.util.ITickable {

	public ItemStack slots[];

	private String customName;

	public TileEntityMachineBase(int slotCount) {
		slots = new ItemStack[slotCount];
	}

	/** The "chunks is modified, pls don't forget to save me" effect of markDirty, minus the block updates */
	public void markChanged() {
		this.world.markTileEntityChunkModified(this.xCoord, this.yCoord, this.zCoord, this);
	}

	@Override
	public int getSizeInventory() {
		return slots.length;
	}

	@Override
	public ItemStack getStackInSlot(int i) {
		return slots[i];
	}

	@Override
	public ItemStack getStackInSlotOnClosing(int i) {
		if(slots[i] != null)
		{
			ItemStack itemStack = slots[i];
			slots[i] = null;
			return itemStack;
		} else {
		return null;
		}
	}

	@Override
	public void setInventorySlotContents(int i, ItemStack itemStack) {
		slots[i] = itemStack;
		if(itemStack != null && itemStack.stackSize > getInventoryStackLimit())
		{
			itemStack.stackSize = getInventoryStackLimit();
		}
	}

	@Override
	public String getName() {
		return this.hasCustomName() ? this.customName : getDefaultName();
	}

	public abstract String getDefaultName();

	@Override
	public net.minecraft.util.text.ITextComponent getDisplayName() {
		return hasCustomName() ? new net.minecraft.util.text.TextComponentString(getName()) : new net.minecraft.util.text.TextComponentTranslation(getName());
	}

	/** Narrow compatibility for existing machine GUI/container callers. */
	public String getInventoryName() { return getName(); }

	/** Narrow compatibility for existing machine GUI/container callers. */
	public boolean hasCustomInventoryName() { return hasCustomName(); }

	@Override
	public boolean hasCustomName() {
		return this.customName != null && this.customName.length() > 0;
	}

	public void setCustomName(String name) {
		this.customName = name;
		markDirty();
	}

	@Override
	public int getInventoryStackLimit() {
		return 64;
	}

	@Override
	public boolean isUsableByPlayer(EntityPlayer player) {
		if(world.getTileEntity(pos) != this) {
			return false;
		} else {
			return player.getDistanceSq(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D) <= 128;
		}
	}

	@Override
	public void openInventory(EntityPlayer player) {}
	@Override
	public void closeInventory(EntityPlayer player) {}

	@Override
	public boolean isItemValidForSlot(int slot, ItemStack itemStack) {
		return false;
	}

	@Override
	public ItemStack decrStackSize(int slot, int amount) {
		if(slots[slot] != null) {

			if(slots[slot].stackSize <= amount) {
				ItemStack itemStack = slots[slot];
				slots[slot] = null;
				return itemStack;
			}

			ItemStack itemStack1 = slots[slot].splitStack(amount);
			if(slots[slot].stackSize == 0) {
				slots[slot] = null;
			}

			return itemStack1;
		} else {
			return null;
		}
	}

	@Override
	public boolean canInsertItem(int slot, ItemStack itemStack, net.minecraft.util.EnumFacing nativeFace) {
		int side = com.hbm.lib.ForgeDirection.fromEnumFacing(nativeFace).ordinal();
		return this.isItemValidForSlot(slot, itemStack);
	}

	@Override
	public boolean canExtractItem(int slot, ItemStack itemStack, net.minecraft.util.EnumFacing nativeFace) {
		int side = com.hbm.lib.ForgeDirection.fromEnumFacing(nativeFace).ordinal();
		return false;
	}

	@Override
	public int[] getSlotsForFace(net.minecraft.util.EnumFacing nativeFace) {
		int side = com.hbm.lib.ForgeDirection.fromEnumFacing(nativeFace).ordinal();
		return new int[] { };
	}

	public int getGaugeScaled(int i, FluidTank tank) {
		return tank.getFluidAmount() * i / tank.getCapacity();
	}

	//abstracting this method forces child classes to implement it
	//so i don't have to remember the fucking method name
	//was it update? onUpdate? updateTile? did it have any args?
	//shit i don't know man
	@Override
	public abstract void update();

	@Deprecated
	public void handleButtonPacket(int value, int meta) { }

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);
		NBTTagList list = nbt.getTagList("items", 10);

		for(int i = 0; i < list.tagCount(); i++)
		{
			NBTTagCompound nbt1 = list.getCompoundTagAt(i);
			byte b0 = nbt1.getByte("slot");
			if(b0 >= 0 && b0 < slots.length)
			{
				slots[b0] = ItemStack.loadItemStackFromNBT(nbt1);
			}
		}

		customName = nbt.getString("name");
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		super.writeToNBT(nbt);
		NBTTagList list = new NBTTagList();

		for(int i = 0; i < slots.length; i++)
		{
			if(slots[i] != null)
			{
				NBTTagCompound nbt1 = new NBTTagCompound();
				nbt1.setByte("slot", (byte)i);
				slots[i].writeToNBT(nbt1);
				list.appendTag(nbt1);
			}
		}
		nbt.setTag("items", list);

		if (customName != null) {
			nbt.setString("name", customName);
		}
		return nbt;
	}

	public void updateRedstoneConnection(DirPos pos) {

		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();
		ForgeDirection dir = pos.getDir();
		Block block1 = worldObj.getBlock(x, y, z);

		block1.onNeighborChange(worldObj, x, y, z, xCoord, yCoord, zCoord);
		block1.onNeighborBlockChange(worldObj, x, y, z, this.getBlockType());
		if(block1.isNormalCube(worldObj, x, y, z)) {
			x += dir.offsetX;
			y += dir.offsetY;
			z += dir.offsetZ;
			Block block2 = worldObj.getBlock(x, y, z);

			if(block2.getWeakChanges(worldObj, x, y, z)) {
				block2.onNeighborChange(worldObj, x, y, z, xCoord, yCoord, zCoord);
				block2.onNeighborBlockChange(worldObj, x, y, z, this.getBlockType());
			}
		}
	}

	// TODO: Consume air from connected tanks if available
	public boolean breatheAir(int amount) {
		return breatheAir(worldObj, xCoord, yCoord, zCoord, amount);
	}

	public static boolean breatheAir(World world, int x, int y, int z, int amount) {
		CBT_Atmosphere atmosphere = world.provider instanceof WorldProviderOrbit ? null : CelestialBody.getTrait(world, CBT_Atmosphere.class);
		if(atmosphere != null) {
			if(atmosphere.hasFluid(Fluids.EARTHAIR, 0.19) || atmosphere.hasFluid(Fluids.OXYGEN, 0.09)) {
				return true;
			}
		}

		List<AtmosphereBlob> blobs = ChunkAtmosphereManager.proxy.getBlobs(world, x, y, z);
		for(AtmosphereBlob blob : blobs) {
			if(blob.hasFluid(Fluids.EARTHAIR, 0.19) || blob.hasFluid(Fluids.OXYGEN, 0.09)) {
				blob.consume(amount);
				return true;
			}
		}

		return false;
	}

}

package com.hbm.tileentity;

import api.hbm.block.ICrucibleAcceptor;
import com.hbm.handler.CompatHandler;
import com.hbm.handler.CompatHandler.OCComponent;
